  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="quiz-card" aria-labelledby="quiz-title">
        <h1 id="quiz-title">Computer Languages Quiz</h1>
        <p class="intro">Choose every answer that applies for each question, then submit your selections.</p>

        <form id="quiz-form" novalidate>
          <div class="form-field">
            <fieldset aria-describedby="question-1-help">
              <legend>1. Which of these are programming languages?</legend>
              <p class="help-text" id="question-1-help">Select all choices that are used to write executable computer programs.</p>
              <div class="choices">
                <label>
                  <input type="checkbox" name="programming-languages" value="python">
                  <span>Python</span>
                </label>
                <label>
                  <input type="checkbox" name="programming-languages" value="html">
                  <span>HTML</span>
                </label>
                <label>
                  <input type="checkbox" name="programming-languages" value="java">
                  <span>Java</span>
                </label>
                <label>
                  <input type="checkbox" name="programming-languages" value="sql">
                  <span>SQL</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>2. Which languages are commonly used for styling or structuring web pages?</legend>
              <div class="choices">
                <label>
                  <input type="checkbox" name="web-languages" value="css">
                  <span>CSS</span>
                </label>
                <label>
                  <input type="checkbox" name="web-languages" value="html">
                  <span>HTML</span>
                </label>
                <label>
                  <input type="checkbox" name="web-languages" value="c">
                  <span>C</span>
                </label>
                <label>
                  <input type="checkbox" name="web-languages" value="javascript">
                  <span>JavaScript</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>3. Which languages are often associated with data querying or analysis?</legend>
              <div class="choices">
                <label>
                  <input type="checkbox" name="data-languages" value="sql">
                  <span>SQL</span>
                </label>
                <label>
                  <input type="checkbox" name="data-languages" value="r">
                  <span>R</span>
                </label>
                <label>
                  <input type="checkbox" name="data-languages" value="python">
                  <span>Python</span>
                </label>
                <label>
                  <input type="checkbox" name="data-languages" value="swift">
                  <span>Swift</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit answers</button>
            <p class="result" id="quiz-result" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#quiz-form");
      const result = document.querySelector("#quiz-result");
      const questionNames = ["programming-languages", "web-languages", "data-languages"];

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        const answeredCount = questionNames.filter((name) => {
          return form.querySelectorAll(`input[name="${name}"]:checked`).length > 0;
        }).length;

        if (answeredCount < questionNames.length) {
          result.textContent = "Please choose at least one answer for each question.";
          result.classList.add("error");
          return;
        }

        result.textContent = "Thanks! Your quiz answers have been submitted.";
        result.classList.remove("error");
      });
    </script>
  </body>
</html>
