                  <span>SQL</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>2. Which languages are commonly used for styling or structuring web pages?</legend>
              <div class="choices">
                <label>
                  <input class="choice-input" type="checkbox" name="web-languages" value="css">
                  <span>CSS</span>
                </label>
                <label>
                  <input class="choice-input" type="checkbox" name="web-languages" value="html">
                  <span>HTML</span>
                </label>
                <label>
                  <input class="choice-input" type="checkbox" name="web-languages" value="c">
                  <span>C</span>
                </label>
                <label>
                  <input class="choice-input" type="checkbox" name="web-languages" value="javascript">
                  <span>JavaScript</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>3. Which languages are often associated with data querying or analysis?</legend>
              <div class="choices">
                <label>
                  <input class="choice-input" type="checkbox" name="data-languages" value="sql">
                  <span>SQL</span>
                </label>
                <label>
                  <input class="choice-input" type="checkbox" name="data-languages" value="r">
                  <span>R</span>
                </label>
                <label>
                  <input class="choice-input" type="checkbox" name="data-languages" value="python">
                  <span>Python</span>
                </label>
                <label>
                  <input class="choice-input" type="checkbox" name="data-languages" value="swift">
                  <span>Swift</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit answers</button>
            <p class="result" id="quiz-result" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#quiz-form");
      const result = document.querySelector("#quiz-result");
      const questionNames = ["programming-languages", "web-languages", "data-languages"];

