                  <span>SQL</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="form-field">
            <fieldset>
              <legend>2. Which languages are commonly used for styling or structuring web pages?</legend>
              <div class="choices">
                <label>
                  <input class="choice-input" type="checkbox" name="web-languages" value="css">
                  <span>CSS</span>
                </label>
                <label>
